<template>
 <view class="native-page">
  <view class="mast"><text class="title">{{ config?.title || '生产业务' }}</text><text class="scope">{{ farmName || '当前经营主体' }}</text></view>
  <view v-if="!config" class="card">当前业务尚未配置，请返回全部业务。</view>
  <template v-else>
   <scroll-view scroll-x class="tabs"><view class="tabline"><view class="ui-measured-touch" v-for="section in config.sections" :key="section.key" :class="['tab',{active:active===section.key}]" @click="changeSection(section.key)">{{ section.label }}</view></view></scroll-view>
   <view class="tools"><view v-if="resource.search" class="search"><input v-model="keyword" placeholder="搜索当前业务" confirm-type="search" @confirm="reload"/><text class="ui-measured-touch" @click="reload">搜索</text></view><view class="actions"><button v-if="resource.filters?.length" size="mini" @click="filtersOpen=!filtersOpen">筛选{{ filtered?' · 已选':'' }}</button><button size="mini" @click="reload">刷新</button><button v-if="resource.key==='alerts'" size="mini" @click="openAlertReview()">复盘与跟进</button><button v-if="!resource.singleton" size="mini" :disabled="busy||loading" @click="exportAll">导出筛选结果</button><button v-if="['farms','inputs'].includes(resource.key)" size="mini" @click="goImport">导入CSV</button><button v-if="target.includes('/growth') || target==='/production/monitor'" size="mini" @click="goAnalysis">对比与趋势</button><button v-if="resource.create" size="mini" class="primary" @click="openCreate">新增{{ resource.label }}</button></view></view>
   <view v-if="filtersOpen" class="card"><business-fields :fields="resource.filters || []" v-model="filters" :farm-id="farmId"/><view class="actions"><button size="mini" @click="resetFilters">重置</button><button size="mini" class="primary" @click="applyFilters">查看结果</button></view></view>
   <view v-if="resource.key==='codes'" class="tools"><view class="actions"><button size="mini" :disabled="busy" @click="selectCodes">全选已加载</button><button size="mini" :disabled="busy||!codes.length" @click="batchCodes('activate')">激活（{{codes.length}}）</button><button size="mini" :disabled="busy||!codes.length" @click="batchCodes('expire')">作废所选</button><button size="mini" :disabled="busy" @click="batchCodes('expire-overdue')">扫描过期码</button></view></view><view v-if="target==='/production/ai/yield-forecast'" class="card"><business-fields :fields="[text('crop','行情作物',true)]" v-model="marketForm"/><view class="actions"><button size="mini" :disabled="busy" @click="marketAction(false)">查询真实行情</button><button size="mini" :disabled="busy" @click="marketAction(true)">刷新官方行情</button></view><business-detail v-if="market" :value="market"/></view><view v-if="resource.hint" class="notice">{{ resource.hint }}</view>
   <view v-if="error" class="error"><text>{{ error }}</text><button size="mini" @click="reload">重试</button></view>
   <text v-if="!error" class="count">{{ loading ? '正在加载…' : `共 ${total} 条` }}</text>
   <view v-for="(row,index) in rows" :key="String(row[resource.id || 'id'] ?? index)" class="ui-measured-touch record" @click="openDetail(row)"><view class="record-head"><checkbox v-if="resource.key==='codes'" :checked="codes.includes(String(row.code))" @click.stop="toggleCode(String(row.code))" color="#126d43"/><text class="record-title">{{ row[resource.title] || resource.label }}</text><text class="arrow">›</text></view><view v-if="!resource.singleton" class="meta"><text v-for="key in resource.subtitle || []" :key="key" v-show="row[key]!==undefined && row[key]!==null">{{ display(row[key],key) }}</text></view><business-detail v-if="resource.singleton" :value="row"/><text class="record-foot">查看详情与操作</text></view>
   <view v-if="!loading&&!error&&!rows.length" class="empty">暂无{{resource.label}}<text>可调整筛选条件{{resource.create?'，或新增记录':''}}</text></view>
   <button v-if="rows.length<total&&!resource.singleton" class="more" :loading="loading" @click="loadMore">加载更多</button>
  </template>
  <view v-if="detailOpen" class="overlay"><view class="sheet-head"><text>{{ actionResult ? actionResultTitle : resource.label+'详情' }}</text><button size="mini" :disabled="busy" @click="closeDetail">关闭</button></view><scroll-view scroll-y class="sheet-body"><view v-if="detailLoading" class="empty">正在加载详情…</view><view v-if="detailError" class="error">{{detailError}}<button size="mini" @click="openDetail(selected)">重试</button></view><business-detail v-else :value="actionResult || selected"/><button v-if="!detailLoading&&!detailError" size="mini" :disabled="busy" @click="exportDetail">导出当前明细</button><view class="safe-space"/></scroll-view><view v-if="!actionResult && !detailLoading && !detailError" class="bottom-actions"><button v-if="canEdit" size="mini" @click="openEdit">编辑</button><button v-if="resource.key==='alerts' && [3,4].includes(Number(selected.status))" size="mini" @click="openAlertReview(String(selected.alertId))">复盘记录</button><button v-for="action in visibleActions" :key="action.key" size="mini" :class="{danger:action.danger}" :disabled="busy" @click="openAction(action)">{{ action.label }}</button></view></view>
  <view v-if="editor" class="overlay editor"><view class="sheet-head"><text>{{ editor.title }}</text><button size="mini" :disabled="busy" @click="editor=undefined">取消</button></view><scroll-view scroll-y class="sheet-body"><view v-if="!editor.fields.length" class="notice">确认执行「{{editor.title}}」？操作结果以服务端校验为准。</view><business-fields :fields="editor.fields" v-model="form" :farm-id="farmId" :disabled="busy" @ready="formReady=$event"/><view v-if="saveError" class="error">{{saveError}}</view><view class="safe-space"/></scroll-view><view class="bottom-actions"><button class="primary save" :loading="busy" :disabled="busy||!formReady" @click="save">{{busy?'保存中…':editor.title}}</button></view></view>
 </view>
</template>
<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, watch } from 'vue'
import {allRows,csv,saveText,contextGuard} from '@/utils/business-files'
import { onLoad,onShow,onHide,onPullDownRefresh,onReachBottom,onBackPress } from '@dcloudio/uni-app'
import { catalog } from '@/api/native-business-catalog'
import { call,fetchResource,endpoint,statusLabels,validateFields,text } from '@/api/native-business'
import type { Row,Resource,Field,Action,Method } from '@/api/native-business'
import { ensureWorkspaceSession,isProductionOps } from '@/utils/workspace'
import { resolveCurrentFarm } from '@/utils/auth-helper'
import { productionContextVersion } from '@/utils/request'
import BusinessFields from '@/components/business-fields/business-fields.vue'
import BusinessDetail from '@/components/business-detail/business-detail.vue'
const codes=ref<string[]>([]),marketForm=ref<Row>({}),market=ref<Row>()
const target=ref(''),active=ref(''),farmId=ref(''),farmName=ref(''),keyword=ref(''),filters=ref<Row>({}),filtersOpen=ref(false)
const rows=ref<Row[]>([]),total=ref(0),loading=ref(false),error=ref(''),busy=ref(false),saveError=ref(''),formReady=ref(false)
const selected=ref<Row>({}),detailOpen=ref(false),detailLoading=ref(false),detailError=ref(''),actionResult=ref<any>(),actionResultTitle=ref('')
const form=ref<Row>({}),editor=ref<{title:string;fields:Field[];url:string;method:Method;query?:boolean;defaults?:Row;action?:Action}>()
let page=1,version=0,detailVersion=0,scopeVersion=0
const config=computed(()=>catalog[target.value])
const resource=computed<Resource>(()=>config.value?.sections.find(s=>s.key===active.value)||config.value?.sections[0]||{key:'',label:'',url:'',title:''})
const canEdit=computed(()=>!!resource.value.edit && (resource.value.key!=='settings'||String(selected.value.configKey||'').startsWith('custom.')))
const filtered=computed(()=>Object.values(filters.value).some(v=>v!==''&&v!==undefined))
const visibleActions=computed(()=>(resource.value.actions||[]).filter(a=>(!a.states||a.states.includes(selected.value[a.stateKey||'status'])) && (resource.value.key!=='diffs'||a.key!=='handle'||(selected.value.ownerSide==='PRODUCTION'&&['PENDING','OPEN','PROCESSING'].includes(selected.value.status)))))
const display=(v:any,key='')=>{if(key==='status'&&resource.value.key==='alerts')return ({1:'未处理',2:'处理中',3:'已处理',4:'已忽略'} as Row)[v]||String(v);const names:Row={availableQty:'可供数量',reservedQty:'已认购',remainingQty:'剩余可供',periodPaidQty:'本期支付量',periodReleasedQty:'本期释放量',periodNetQty:'本期净增量',tradedQty:'成交量',supplyQty:'供给量',tradeStatus:'交易状态',auditStatus:'审核状态'};if(names[key])return names[key]+'：'+(statusLabels[String(v)]||String(v));if(key==='status'&&resource.value.key==='plans')return ({1:'编制中',2:'进行中',3:'已完结',4:'已取消',5:'待审批'} as Row)[v]||String(v);return statusLabels[String(v)]||String(v)}
async function marketAction(refresh:boolean){if(busy.value)return;error.value='';market.value=undefined;try{if(!marketForm.value.crop?.trim())throw new Error('请填写行情作物');busy.value=true;const guard=contextGuard();if(refresh){const result=await call('/yield-forecasts/market/sync','POST',undefined,{source:'NX'});guard();if(result.status==='FAILED')throw new Error(result.error||'行情刷新失败')}const result=await call('/yield-forecasts/market','GET',undefined,{crop:marketForm.value.crop.trim()});guard();market.value=result}catch(e:any){error.value=e.message}finally{busy.value=false}}
function toggleCode(code:string){codes.value=codes.value.includes(code)?codes.value.filter(c=>c!==code):[...codes.value,code]}
function selectCodes(){codes.value=rows.value.map(r=>String(r.code))}
async function batchCodes(action:string){if(busy.value)return;const selectedCodes=[...codes.value],guard=contextGuard();const yes=await new Promise<boolean>(resolve=>uni.showModal({title:action==='expire-overdue'?'扫描本主体过期码？':`确认处理${selectedCodes.length}个溯源码？`,content:action==='expire'?'作废后将不能正常使用。':'服务端将校验码状态和操作权限。',success:r=>resolve(r.confirm),fail:()=>resolve(false)}));if(!yes)return;busy.value=true;try{guard();const count=await call('/trace/codes/'+action,'PUT',action==='expire-overdue'?undefined:{codes:selectedCodes});guard();await reload();uni.showToast({title:`已处理${count}条`,icon:'none'})}catch(e:any){error.value=e.message}finally{busy.value=false}}
function openAlertReview(id?:string){uni.navigateTo({url:'/pages/alerts/review'+(id?'?alertId='+encodeURIComponent(id):'')})}
function goImport(){uni.navigateTo({url:'/pages/native/import?kind='+resource.value.key})}
function goAnalysis(){uni.navigateTo({url:'/pages/native/growth-analysis?mode='+(resource.value.key==='environment'?'environment':'growth')})}
async function exportAll(){if(busy.value)return;busy.value=true;error.value='';try{const currentVersion=version,scopeGuard=contextGuard(),savedResource=resource.value;const query=validateFields(savedResource.filters||[],filters.value);for(const [start,end] of [['startDate','endDate'],['from','to']])if(query[start]&&query[end]&&query[start]>query[end])throw new Error('结束日期不能早于开始日期');const guard=()=>{scopeGuard();if(version!==currentVersion||resource.value!==savedResource)throw new Error('页面或筛选已变化，导出已取消')};const params:Row={...query,...(farmId.value?{farmId:farmId.value}:{})};if(savedResource.search&&keyword.value.trim())params[savedResource.search]=keyword.value.trim();const list=await allRows(savedResource,params,guard);guard();if(params.offerNo&&list.some(r=>r.offerNo!==params.offerNo))throw new Error('返回的供给范围不一致，导出已取消');const keys=[...new Set([resource.value.id||'id',resource.value.title,...(resource.value.subtitle||[]),...(resource.value.fields||[]).map(f=>f.key)])];await saveText(resource.value.label+'-筛选全部.csv',csv(list,keys.map(key=>({key,label:resource.value.fields?.find(f=>f.key===key)?.label||({[resource.value.title]:'名称',status:'状态',createdAt:'创建时间',collectedAt:'采集时间',airTemperature:'温度℃',airHumidity:'湿度%',soilMoisture:'土壤水分',qty:'数量',batchNo:'批次号',flowType:'流水类型'} as Row)[key]||key}))))}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function exportDetail(){try{if(scopeVersion!==productionContextVersion()||isProductionOps())throw new Error('业务范围已变化');await saveText(resource.value.label+'-当前明细.json',JSON.stringify(actionResult.value||selected.value,null,2))}catch(e:any){detailError.value=e.message}}
function closeDetail(){if(busy.value)return;detailOpen.value=false;detailVersion++;actionResult.value=undefined}
function changeSection(key:string){if(busy.value)return;active.value=key;filters.value={};keyword.value='';closeDetail();void reload()}
function applyFilters(){filtersOpen.value=false;void reload()}
function resetFilters(){filters.value={};void reload()}
async function initialize(){if(!await ensureWorkspaceSession())return;if(isProductionOps()){error.value='请到「我的」切换到用户端';rows.value=[];return}try{if(config.value?.farm){const farm=await resolveCurrentFarm();if(!farm)return;farmId.value=String(farm.farmId);farmName.value=farm.farmName||''}if(scopeVersion!==productionContextVersion()){rows.value=[];selected.value={};editor.value=undefined;detailOpen.value=false;filters.value={}}scopeVersion=productionContextVersion();await reload()}catch(e:any){error.value=e.message}}
async function load(more=false){if(!more)codes.value=[];if(!config.value || isProductionOps())return;const current=++version;loading.value=true;error.value='';const next=more?page+1:1;if(!more){rows.value=[];total.value=0}try{for(const f of resource.value.filters||[])if(f.required&&!filters.value[f.key]){filtersOpen.value=true;throw new Error('请先选择'+f.label)}const params:Row={...filters.value,...(farmId.value?{farmId:farmId.value}:{})};if(resource.value.search&&keyword.value.trim())params[resource.value.search]=keyword.value.trim();const result=await fetchResource(resource.value,params,next);if(current!==version)return;rows.value=more?rows.value.concat(result.list):result.list;total.value=result.total;page=next}catch(e:any){if(current===version)error.value=e.message||'加载失败'}finally{if(current===version){loading.value=false;uni.stopPullDownRefresh()}}}
const reload=()=>load(false)
const loadMore=()=>{if(!loading.value&&rows.value.length<total.value)void load(true)}
async function openDetail(row:Row){if(busy.value)return;selected.value=row;detailOpen.value=true;actionResult.value=undefined;detailError.value='';detailLoading.value=false;const current=++detailVersion;if(!resource.value.detail)return;detailLoading.value=true;try{const result=await call(endpoint(resource.value.detail,row));if(current===detailVersion)selected.value=result}catch(e:any){if(current===detailVersion)detailError.value=e.message}finally{if(current===detailVersion)detailLoading.value=false}}
function defaults(fields:Field[]){return Object.fromEntries(fields.map(f=>[f.key,f.default??((f.multiple||f.type==='images'||f.type==='array')?[]:'')]))}
function openCreate(){formReady.value=false;saveError.value='';const fields=resource.value.fields||[];form.value=defaults(fields);editor.value={title:'新增'+resource.value.label,fields,url:resource.value.create!,method:'POST',query:resource.value.createQuery};formReady.value=false}
function openEdit(){if(!canEdit.value)return;formReady.value=false;saveError.value='';form.value={...selected.value};editor.value={title:'保存修改',fields:resource.value.fields||[],url:endpoint(resource.value.edit!,selected.value),method:resource.value.edit?.endsWith('/save')?'POST':'PUT'};formReady.value=false}
async function openAction(action:Action){saveError.value='';if(action.method==='GET'){busy.value=true;try{actionResult.value=await call(endpoint(action.url,selected.value),'GET',undefined,{...selected.value,farmId:farmId.value||undefined});actionResultTitle.value=action.label}catch(e:any){detailError.value=e.message}finally{busy.value=false}return}form.value={...defaults(action.fields||[])};editor.value={title:action.label,fields:action.fields||[],url:endpoint(action.url,selected.value),method:action.method||'POST',query:action.query,defaults:action.defaults,action};formReady.value=false}
async function save(){if(busy.value||!editor.value)return;saveError.value='';const current=editor.value;try{if(scopeVersion!==productionContextVersion()||isProductionOps())throw new Error('业务范围已变更，请返回后重新打开');const payload:Row={...(current.defaults||{}),...validateFields(current.fields,form.value)};
if(farmId.value)payload.farmId=farmId.value
if(target.value==='/production/harvests/inventory' && current.action){payload.inventoryId=selected.value.inventoryId;payload.batchId=selected.value.batchId}
if(resource.value.key==='settings'){if(!canEdit.value||payload.configKey!==selected.value.configKey)throw new Error('只能修改当前自定义配置的值');Object.assign(payload,{settingKey:payload.configKey,settingValue:payload.configValue,remark:payload.description});delete payload.configKey;delete payload.configValue;delete payload.description}
if(current.action?.key==='activate')payload.code=selected.value.code
if(current.url==='/input-safety/check'||current.url==='/ai/pest-detection')payload.requestId='mobile-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)
if(current.action?.key==='handle'&&target.value.includes('/p2t')){if(!['PROCESSING','CLOSED'].includes(payload.status))throw new Error('请选择有效处理状态');if(selected.value.ownerSide!=='PRODUCTION'||!['PENDING','OPEN','PROCESSING'].includes(selected.value.status))throw new Error('当前工单仅可查看');if(String(payload.remark||'').length>200)throw new Error('处理说明不能超过200字');if(payload.status==='CLOSED'){if(selected.value.status!=='PROCESSING')throw new Error('请先登记处理过程，再核验关闭');if(!['补发','降级','退款'].includes(payload.handleWay))throw new Error('其他方式暂无可核验凭据，请保留处理中');if(!/^[A-Za-z0-9_-]{1,64}$/.test(payload.evidenceNo||''))throw new Error('请填写有效凭据编号（最多64个字母、数字、下划线或连字符）')}payload.expectedStatus=selected.value.status}
if(target.value==='/production/quality'&&!current.action)payload.status=selected.value.status || 'PENDING'
for(const [start,end] of [['startDate','endDate'],['planStartDate','planEndDate'],['availableFrom','availableTo'],['windowStart','windowEnd']])if(payload[start]&&payload[end]&&payload[start]>payload[end])throw new Error('结束日期不能早于开始日期')
if(current.action?.danger || current.action?.method==='DELETE'){const confirmed=await new Promise<boolean>(resolve=>uni.showModal({title:'请确认操作',content:`将执行「${current.title}」，该操作可能影响业务记录，是否继续？`,success:r=>resolve(r.confirm),fail:()=>resolve(false)}));if(!confirmed)return}
	busy.value=true;const result=await call(current.url,current.method,current.query?undefined:payload,current.query?payload:undefined);if(scopeVersion!==productionContextVersion())return;if(resource.value.key==='settings'){const stored=await call('/settings/by-key','GET',undefined,{settingKey:payload.settingKey});if(scopeVersion!==productionContextVersion())return;if(!stored||stored.settingValue!==payload.settingValue||(payload.remark&&stored.remark!==payload.remark))throw new Error('保存已提交但回读不一致，请刷新核对，勿重复提交')}editor.value=undefined;detailOpen.value=false;uni.showToast({title:'已保存',icon:'success'});await reload();if(current.action?.result || current.url.includes('/infer') || current.url.includes('/check') || current.url==='/tech-learning/qa'){actionResult.value=result;actionResultTitle.value=current.title;detailOpen.value=true}
}catch(e:any){saveError.value=e.message||'保存失败，请重试'}finally{busy.value=false}}
function setTarget(value:string){const next=decodeURIComponent(value);if(next===target.value)return;version++;target.value=next;active.value=config.value?.sections[0]?.key||'';rows.value=[];total.value=0;selected.value={};filters.value={};keyword.value='';farmId.value='';farmName.value='';detailOpen.value=false;editor.value=undefined;uni.setNavigationBarTitle({title:config.value?.title||'生产业务'})}
watch(()=>form.value.cropName,(crop,old)=>{if(target.value!=='/production/ai/yield-forecast'||!editor.value)return;const field=editor.value.fields.find(f=>f.key==='marketQuoteId');if(field){editor.value.fields=editor.value.fields.map(f=>f.key==='marketQuoteId'?{...f,sourceParams:{crop}}:f);if(crop!==old)form.value.marketQuoteId=''}})
onLoad(options=>setTarget(options?.target||''))
// #ifdef H5
function syncHash(){const hash=window.location.hash;if(!hash.includes('/pages/native/business?'))return;const value=new URLSearchParams(hash.split('?')[1]||'').get('target');if(value&&value!==target.value){setTarget(value);void initialize()}}
onMounted(()=>window.addEventListener('hashchange',syncHash))
onUnmounted(()=>window.removeEventListener('hashchange',syncHash))
// #endif
onShow(()=>void initialize())
onHide(()=>{version++;detailVersion++;loading.value=false;editor.value=undefined;detailOpen.value=false})
onPullDownRefresh(()=>void reload())
onReachBottom(loadMore)
onBackPress(()=>{if(busy.value)return true;if(editor.value){editor.value=undefined;return true}if(detailOpen.value){closeDetail();return true}return false})
</script>
